import { Buffer, GpuContext } from 'wgpu-kit';
import { createNeighborGrid } from 'wgpu-kit/grid';
const pos = await Buffer.create('vec2f', 3);
pos.write(new Float32Array([-0.5, 0, 0, 0, 0.5, 0]));
const grid = await createNeighborGrid({ count: 3, worldHalf: 1, cellSize: 0.25 });
await grid.prepare();
const ctx = await GpuContext.get();
const encoder = ctx.device.createCommandEncoder();
grid.encode(encoder, pos);
// Encode downstream consumers of grid.cellStart/cellFill/order here.
ctx.device.queue.submit([encoder.finish()]);
grid.endSubmit();
const starts = await grid.cellStart.read();
const ends = await grid.cellFill.read();
const order = await grid.order.read();
console.log(starts, ends, order);
grid.destroy();
pos.destroy();

import { Buffer, createBatch } from 'wgpu-kit';
import { createNeighborGrid } from 'wgpu-kit/grid';
const pos = await Buffer.create('vec2f', 2);
pos.write(new Float32Array([-0.2, 0, 0.2, 0]));
const grid = await createNeighborGrid({ count: 2, worldHalf: 1, cellSize: 0.25 });
await grid.prepare();
const batch = await createBatch();
grid.encode(batch.encoder, pos, batch);
// Append a consumer of cellStart/cellFill/order before another build.
batch.submit();
console.log(await grid.order.read());
grid.destroy(); pos.destroy();
